const results = [];

for (const item of $input.all()) {
  (item.json.results || []).forEach(it => {
    const { url, title, content } = it;
    results.push({ url, title, content });
  });
}

return [{ json: { results } }];

const raw = $input.first().json.niche || "";

const niches = raw.split(",").map(s => s.trim()).filter(Boolean);

return niches.map(niche => ({ json: { niche, pages: $input.first().json.pages } }));
